/**
 * The image manifest and what pages and plugins read from it. The images are
 * pregenerated by `pnpm images` (scripts/generate-images.ts) in fixed WebP
 * widths under public/images/, so the build processes no images.
 *
 * An image's key is its URL path below /images/, as the texts use it:
 * `/images/kamae/ichimonji.webp` → `kamae/ichimonji.webp`,
 * `/images/old/chronology/history-1999.jpg` → `old/chronology/history-1999.jpg`.
 */
import manifestJson from './manifest.json' with { type: 'json' };

export interface ImageEntry {
	/** Size of the original */
	width: number;
	height: number;
	/** width / height, 4 decimals */
	aspect: number;
	/** `object-position` from kogakure-texts' mapping.csv, e.g. `50% 18%` */
	focus?: string;
	/** Generated WebP widths, ascending */
	widths: number[];
	/** Hash of the source and the settings: the script skips unchanged images */
	hash: string;
}

export interface OgEntry {
	/** Key of the opener the OG image is cropped from */
	image: string;
	hash: string;
}

export interface InkEntry {
	width: number;
	height: number;
	hash: string;
}

export interface Manifest {
	images: Record<string, ImageEntry>;
	/** OG images by translationKey */
	og: Record<string, OgEntry>;
	/** Ink assets of the design by file name */
	ink: Record<string, InkEntry>;
}

export const manifest: Manifest = manifestJson;

/** Widths of every image; the script never enlarges past the largest source */
export const WIDTHS = [800, 1400, 2000] as const;
/** Paintings also come as full-width bands (the opener and the homepage plates) */
export const BAND_WIDTH = 2750;
/** The `src` fallback: the largest width up to this */
const FALLBACK_WIDTH = 1400;

/**
 * `sizes` of the layouts (DESIGN.md): figures are `min(44em, 100vw - 2 ×
 * gutter)`, the opener and the full-width bands fill the 86rem page
 */
export const SIZES = {
	figure: '(min-width: 48em) 44em, 100vw',
	band: '(min-width: 86rem) 82rem, 100vw',
} as const;

export const OG_SIZE = { width: 1200, height: 630 } as const;

/** Paintings, as opposed to diagrams, objects and technique images */
const PAINTING = /^(article|historical)\//;
export const isPainting = (key: string): boolean => PAINTING.test(key);

/** `/images/kamae/ichimonji.webp` → `kamae/ichimonji.webp`; undefined outside /images/ */
export const imageKey = (url: string): string | undefined =>
	url.startsWith('/images/') ? url.slice('/images/'.length) : undefined;

/** URL of the generated file of an image in one width */
export const imageFile = (key: string, width: number): string =>
	`/images/${key.replace(/\.[^./]+$/, '')}-${width}.webp`;

export const ogFile = (translationKey: string): string => `/images/og/${translationKey}.jpg`;

export const inkFile = (name: string): string => `/images/ink/${name}`;

/** What an `<img>` needs */
export interface ResponsiveImage {
	src: string;
	srcset: string;
	/** Size of the original, for the aspect ratio against layout shift */
	width: number;
	height: number;
	focus?: string;
}

export function getImage(url: string, from: Manifest = manifest): ResponsiveImage | undefined {
	const key = imageKey(url);
	const entry = key === undefined ? undefined : from.images[key];
	if (!key || !entry) return undefined;
	const fallback = entry.widths.findLast((w) => w <= FALLBACK_WIDTH) ?? entry.widths[0];
	if (fallback === undefined) return undefined;
	return {
		src: imageFile(key, fallback),
		srcset: entry.widths.map((w) => `${imageFile(key, w)} ${w}w`).join(', '),
		width: entry.width,
		height: entry.height,
		...(entry.focus ? { focus: entry.focus } : {}),
	};
}

/** URLs of all generated files of an image; empty if it isn't in the manifest */
export function generatedFiles(url: string, from: Manifest = manifest): string[] {
	const key = imageKey(url);
	const entry = key === undefined ? undefined : from.images[key];
	return key && entry ? entry.widths.map((w) => imageFile(key, w)) : [];
}

/**
 * The opener of an article: its first painting (`article/`, `historical/`).
 * Diagrams, objects and technique images don't open an article.
 */
export function findOpener(imageUrls: readonly string[]): string | undefined {
	return imageUrls.find((url) => {
		const key = imageKey(url);
		return key !== undefined && isPainting(key);
	});
}

/** The OG image of a page, if its article has an opener */
export const getOgImage = (translationKey: string, from: Manifest = manifest) =>
	from.og[translationKey] ? { src: ogFile(translationKey), ...OG_SIZE } : undefined;

/** `"50% 18%"` → [0.5, 0.18]; the centre for anything else */
export function parseFocus(focus: string | undefined): [number, number] {
	const match = focus?.match(/^(\d+(?:\.\d+)?)% (\d+(?:\.\d+)?)%$/);
	return match ? [Number(match[1]) / 100, Number(match[2]) / 100] : [0.5, 0.5];
}
